-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"QT zeigt jetzt bei der Anmeldung oder beim Neuladen der Benutzeroberfläche einen Tipp aus einem gemischten Vorrat an. Erst wenn alle Tipps gezeigt wurden, wiederholen sie sich.","Du kannst automatische Tipps unter Allgemein auf der Hauptseite der QuestTogether-Einstellungen deaktivieren. /qt tip und /qt hint bleiben verfügbar."},["tip"]={["label"]="Tipp:",["text"]="Gib „/qt tip“ oder „/qt hint“ ein, um jederzeit einen weiteren QuestTogether-Tipp zu sehen."},["title"]="QuestTogether-Tipps"}},["version"]="7.1.1",["welcome"]="Entdecke mit hilfreichen Tipps mehr von QuestTogether."},["esES"]={["sections"]={{["items"]={"QT ahora muestra un consejo al iniciar sesión o recargar la interfaz, elegido de una lista barajada sin repeticiones hasta agotarla.","Puedes desactivar los consejos automáticos en General, en la página principal de ajustes de QuestTogether. /qt tip y /qt hint siguen disponibles."},["tip"]={["label"]="Consejo:",["text"]="Escribe /qt tip o /qt hint para ver otro consejo de QuestTogether cuando quieras."},["title"]="Consejos de QuestTogether"}},["version"]="7.1.1",["welcome"]="Descubre más de QuestTogether con consejos útiles."},["esMX"]={["sections"]={{["items"]={"QT ahora muestra un consejo al iniciar sesión o recargar la interfaz, elegido de una lista barajada sin repeticiones hasta agotarla.","Puedes desactivar los consejos automáticos en General, en la página principal de ajustes de QuestTogether. /qt tip y /qt hint siguen disponibles."},["tip"]={["label"]="Consejo:",["text"]="Escribe /qt tip o /qt hint para ver otro consejo de QuestTogether cuando quieras."},["title"]="Consejos de QuestTogether"}},["version"]="7.1.1",["welcome"]="Descubre más de QuestTogether con consejos útiles."},["frFR"]={["sections"]={{["items"]={"QT affiche désormais une astuce à la connexion ou au rechargement de l’interface, tirée d’une liste mélangée sans répétition tant que toutes les astuces n’ont pas été affichées.","Vous pouvez désactiver les astuces automatiques dans Général sur la page principale des paramètres de QuestTogether. /qt tip et /qt hint restent disponibles."},["tip"]={["label"]="Astuce :",["text"]="Saisissez « /qt tip » ou « /qt hint » pour voir une autre astuce QuestTogether quand vous le souhaitez."},["title"]="Astuces QuestTogether"}},["version"]="7.1.1",["welcome"]="Découvrez davantage de fonctionnalités de QuestTogether grâce à des astuces utiles."},["itIT"]={["sections"]={{["items"]={"QT ora mostra un consiglio all’accesso o al ricaricamento dell’interfaccia, pescando da un elenco mescolato senza ripetizioni finché non sono stati mostrati tutti.","Puoi disattivare i consigli automatici in Generale nella pagina principale delle impostazioni di QuestTogether. /qt tip e /qt hint restano disponibili."},["tip"]={["label"]="Consiglio:",["text"]="Digita «/qt tip» o «/qt hint» per vedere un altro consiglio di QuestTogether quando vuoi."},["title"]="Consigli di QuestTogether"}},["version"]="7.1.1",["welcome"]="Scopri altre funzionalità di QuestTogether con consigli utili."},["koKR"]={["sections"]={{["items"]={"이제 로그인하거나 UI를 다시 불러오면 도움말이 표시됩니다. 섞인 목록에서 하나씩 뽑으며, 목록을 모두 볼 때까지 반복되지 않습니다.","QuestTogether 설정의 기본 페이지에서 일반 항목의 자동 도움말을 끌 수 있습니다. /qt tip 및 /qt hint는 계속 사용할 수 있습니다."},["tip"]={["label"]="도움말:",["text"]="언제든 /qt tip 또는 /qt hint를 입력하면 다른 QuestTogether 도움말을 볼 수 있습니다."},["title"]="QuestTogether 도움말"}},["version"]="7.1.1",["welcome"]="유용한 도움말로 QuestTogether의 더 많은 기능을 알아보세요."},["ptBR"]={["sections"]={{["items"]={"O QT agora mostra uma dica ao entrar no jogo ou recarregar a interface, escolhida de uma lista embaralhada sem repetições até ela se esgotar.","Você pode desativar as dicas automáticas em Geral, na página principal de configurações do QuestTogether. /qt tip e /qt hint continuam disponíveis."},["tip"]={["label"]="Dica:",["text"]="Digite /qt tip ou /qt hint para ver outra dica do QuestTogether quando quiser."},["title"]="Dicas do QuestTogether"}},["version"]="7.1.1",["welcome"]="Descubra mais do QuestTogether com dicas úteis."},["ruRU"]={["sections"]={{["items"]={"Теперь QT показывает совет при входе в игру или перезагрузке интерфейса. Советы выбираются из перемешанного списка без повторов, пока он не закончится.","Автоматические советы можно отключить в разделе «Общие» на главной странице настроек QuestTogether. Команды /qt tip и /qt hint останутся доступны."},["tip"]={["label"]="Совет:",["text"]="Введите /qt tip или /qt hint, чтобы в любой момент увидеть ещё один совет QuestTogether."},["title"]="Советы QuestTogether"}},["version"]="7.1.1",["welcome"]="Узнайте больше о QuestTogether с полезными советами."},["zhCN"]={["sections"]={{["items"]={"QT 现在会在登录或重载界面时显示一条提示，从打乱的列表中抽取，整轮看完之前不会重复。","你可以在 QuestTogether 设置主页的“常规”部分关闭自动提示。/qt tip 和 /qt hint 仍可使用。"},["tip"]={["label"]="提示：",["text"]="随时输入 /qt tip 或 /qt hint，即可查看另一条 QuestTogether 提示。"},["title"]="QuestTogether 提示"}},["version"]="7.1.1",["welcome"]="通过实用提示，了解 QuestTogether 的更多功能。"},["zhTW"]={["sections"]={{["items"]={"QT 現在會在登入或重新載入介面時顯示一則提示，從打亂的清單中抽取，整輪看完之前不會重複。","你可以在 QuestTogether 設定主頁的「一般」區塊關閉自動提示。/qt tip 和 /qt hint 仍可使用。"},["tip"]={["label"]="提示：",["text"]="隨時輸入 /qt tip 或 /qt hint，即可查看另一則 QuestTogether 提示。"},["title"]="QuestTogether 提示"}},["version"]="7.1.1",["welcome"]="透過實用提示，認識 QuestTogether 的更多功能。"}}
